<script setup lang="ts">
import {ref} from 'vue';import {useAuth} from '../stores/store';import {useRouter} from 'vue-router';const phone=ref('+255'),code=ref(''),sent=ref(''),dob=ref('');const auth=useAuth(),r=useRouter();function send(){sent.value='123456';alert('Mock SMS code: 123456 (demo only)')}function submit(){if(sent.value&&code.value!=='123456')return alert('Wrong code'); if(dob.value && new Date().getFullYear()-new Date(dob.value).getFullYear()<18)return alert('18+ only'); auth.login(phone.value); r.push('/profile')};
</script>
<template><h2>Login / Register / Forgot</h2><div class="card"><label>Phone (+255)</label><input v-model="phone"/><label>Date of birth (18+)</label><input type="date" v-model="dob"/><button @click="send">Send SMS Code (mock)</button><p v-if="sent">Demo code shown for sandbox: <b>123456</b></p><input v-model="code" placeholder="6-digit code"/><input type="password" placeholder="Password"/><button @click="submit">Continue</button><p><small>Forgot password? Use phone + SMS code above. No real SMS sent.</small></p></div></template>
